  .ts-preview-modal .ts-preview-heading:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {flex-wrap:wrap;gap:10px;}
  .ts-preview-modal .ts-preview-path:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {flex-basis:100%;}
  .ts-preview-modal .ts-preview-body:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {padding-top:20px;}
}

/* BEGIN board-polish generated */
/* Whiteboard chrome: calm surfaces with distinct tool groups.
   This file owns the final canvas chrome. Content geometry, text typography,
   custom fills and source-editor measurements are deliberately unchanged. */
.ts-root .ts-main:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  container-name: ts-board-canvas;
  --ts-board-panel: var(--ts-e-sheet,var(--background-primary));
  --ts-board-line: var(--ts-e-line,var(--background-modifier-border));
  --ts-board-hover: var(--ts-e-wash,var(--background-modifier-hover));
  --ts-board-active: color-mix(in srgb, var(--ts-accent) 9%, var(--ts-e-sheet,var(--background-primary)));
  --ts-board-shadow: 0 1px 3px #00000008, 0 4px 14px #00000009;
  --ts-board-menu-shadow: 0 2px 5px #00000008, 0 14px 36px #00000016;
  --ts-board-control: 32px;
  --ts-board-format-control: 32px;
  --ts-board-format-gap: 2px;
  --ts-board-gutter: 12px;
}
.ts-root[data-toolbar-density=comfortable] .ts-main:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { --ts-board-format-control: 38px; --ts-board-format-gap: 4px; }
.theme-dark .ts-root .ts-main:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  --ts-board-shadow: 0 1px 2px #00000028, 0 5px 18px #00000032;
  --ts-board-menu-shadow: 0 2px 5px #00000032, 0 14px 36px #00000048;
}

/* Grid is a positioning aid, not a second layer competing with note content.
   Its origin and spacing still follow the board transform and snap setting. */
.ts-root :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  background-color: color-mix(in srgb, var(--background-primary) 72%, var(--background-secondary));
  --ts-grid-ink: color-mix(in srgb, var(--text-muted) 9%, transparent);
  --ts-dot-ink: color-mix(in srgb, var(--text-muted) 27%, transparent);
}
.ts-root[data-snap=true] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  --ts-grid-ink: color-mix(in srgb, var(--ts-accent) 12%, transparent);
  --ts-dot-ink: color-mix(in srgb, var(--ts-accent) 36%, transparent);
}
.ts-root[data-background=grid] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  background-image: linear-gradient(to right, var(--ts-grid-ink) 1px, transparent 1px), linear-gradient(to bottom, var(--ts-grid-ink) 1px, transparent 1px);
}
.ts-root[data-background=dots] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background-image: radial-gradient(var(--ts-dot-ink) .8px, transparent .8px); }
/* Neutral paper grain: 384px transparent indexed PNG, seed 100032. Fine
   per-pixel grain and 2000 tiny fibers carry no paper color or cloudy shading.
   The stage and settings preview share paper-grain.png next to styles.css. Opacity is 0..1;
   saved preferences convert the user's 0..100 value before setting the variable. */
.ts-root[data-background=paper]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)), .ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  --ts-paper-grain-image: url("paper-grain.png");
}
.ts-root[data-background=paper] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)),
.ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  position: relative;
  isolation: isolate;
  background-color: var(--ts-paper-color, #f3e9d4);
  background-image: none;
}
.theme-dark .ts-root[data-background=paper] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)),
.theme-dark .ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  background-color: color-mix(in srgb, var(--ts-paper-color, #f3e9d4) 16%, #171918);
}
/* Texture remains in fixed stage pixels, separate from the live grid inline
   backgroundSize/backgroundPosition and the transformed world beneath objects. */
.ts-root[data-background=paper] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *))::before,
.ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *))::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
  background-image: var(--ts-paper-grain-image);
  background-size: 384px 384px;
  background-position: 0 0;
  background-repeat: repeat;
  opacity: clamp(0, var(--ts-paper-texture, .55), 1);
}
.ts-root[data-background=paper] .ts-stage > .ts-world:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { z-index: 1; }
.ts-paper-preview > .ts-paper-preview-content:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { position: relative; z-index: 1; }
/* Only opaque note cards gain a contact shadow. Content fonts, custom fills,
   borders, transparency and media retain their own presentation. */
.ts-root[data-background=paper] .ts-card:not(.is-transparent):not(.ts-media-card):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  box-shadow: 0 1px 2px #493c271a, 0 4px 12px #493c2712;
}
.theme-dark .ts-root[data-background=paper] .ts-card:not(.is-transparent):not(.ts-media-card):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  box-shadow: 0 1px 2px #00000040, 0 5px 14px #00000032;
}
@media (prefers-contrast: more) {
  .ts-root[data-background] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { --ts-grid-ink: color-mix(in srgb, var(--text-muted) 22%, transparent); --ts-dot-ink: var(--text-muted); }
  .ts-root[data-background=paper] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)), .ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background-color: var(--background-primary) !important; }
  .ts-root[data-background=paper] :is(.ts-main > .ts-stage,.ts-brain-stage):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *))::before, .ts-paper-preview:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *))::before { display: none; }
}

/* The starting surface belongs to the stage, outside the transformed world.
   It can scroll on a short pane without moving tools or changing the viewport. */
.ts-root .ts-main .ts-start-screen:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  position: absolute; z-index: 2; left: 50%; top: 50%; transform: translate(-50%, -50%);
  box-sizing: border-box; width: min(520px, calc(100% - 120px)); max-height: calc(100% - 144px);
  padding: 28px; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin;
  border: 1px solid var(--ts-board-line); border-radius: 14px;
  background: var(--ts-board-panel); color: var(--text-normal); text-align: left;
  box-shadow: var(--ts-board-shadow); font-family: var(--font-interface); cursor: default;
}
.ts-root .ts-start-screen[hidden]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { display: none !important; }
.ts-root .ts-start-heading:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { margin: 0; color: var(--text-normal); font-size: clamp(20px, 3cqi, 28px); line-height: 1.4; font-weight: 600; letter-spacing: -.025em; }
.ts-root .ts-start-copy:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { margin: 10px 0 22px; color: var(--text-muted); font-size: 13px; line-height: 1.8; overflow-wrap: anywhere; }
.ts-root .ts-start-actions:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { display: flex; flex-wrap: wrap; gap: 8px; }
.ts-root .ts-start-actions > .ts-button:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  display: inline-flex; align-items: center; justify-content: flex-start; gap: 8px;
  flex: 1 1 120px; min-width: 0; min-height: 38px; height: auto; padding: 9px 11px !important;
  border: 1px solid var(--ts-board-line) !important; border-radius: 7px !important;
  background: var(--ts-board-panel) !important; color: var(--text-normal) !important; font-size: 12px; line-height: 1.5;
  white-space: normal; box-shadow: none; text-align: left;
}
.ts-root .ts-start-actions > .ts-button > span:first-child:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { display: flex; flex: none; color: var(--text-muted); }
.ts-root .ts-start-actions > .ts-button > span:last-child:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { min-width: 0; overflow-wrap: anywhere; }
.ts-root .ts-start-actions > .ts-button svg:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { width: 16px; height: 16px; }
.ts-root .ts-start-actions > .ts-button:hover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { border-color: var(--ts-accent) !important; background: var(--ts-board-active) !important; }
.ts-root .ts-start-actions > .ts-primary:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background: var(--ts-board-active) !important; border-color: color-mix(in srgb, var(--ts-accent) 28%, var(--ts-board-line)) !important; color: var(--text-normal) !important; }
.ts-root .ts-start-actions > .ts-primary > span:first-child:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { color: var(--ts-accent); }
.ts-root .ts-start-tip:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { margin: 20px 0 0; padding-top: 14px; border-top: 1px solid var(--ts-board-line); color: var(--text-muted); font-size: 11px; line-height: 1.7; }
.ts-root .ts-start-screen :is(button, a):focus-visible:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { outline: 2px solid var(--ts-accent); outline-offset: 2px; }

/* The empty board is a small reading invitation. It remains outside the world
   transform and retains its existing short-pane scroll boundary. */
.ts-root .ts-main .ts-start-screen:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { border-radius:12px; border-top:3px solid var(--ts-e-editorial,var(--ts-accent)); color:var(--ts-e-ink,var(--text-normal)); }
.ts-root .ts-start-heading:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { font-family:var(--ts-e-serif,var(--font-text)); font-weight:600; letter-spacing:0; line-height:1.55; text-wrap:balance; color:var(--ts-e-ink,var(--text-normal)); }
.ts-root .ts-start-copy:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { color:var(--ts-e-muted,var(--text-muted)); font-size:14px; line-height:1.9; }
.ts-root .ts-start-actions > .ts-button:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { min-height:44px; border-radius:6px!important; font-size:13px; }
.ts-root .ts-start-actions > .ts-button:active:not(:disabled):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background:var(--ts-board-hover)!important; box-shadow:inset 0 0 0 1px var(--ts-accent); }
.ts-root .ts-start-tip:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { color:var(--ts-e-muted,var(--text-muted)); font-size:12px; line-height:1.8; }

/* The creation rail stays in the actual center of the available canvas. */
.ts-root .ts-main > .ts-board-rail:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  top: 50%;
  left: var(--ts-board-gutter);
  width: 42px;
  max-height: max(40px, calc(100% - 132px));
  border-color: var(--ts-board-line);
  border-radius: 10px;
  background: var(--ts-board-panel);
  box-shadow: var(--ts-board-shadow);
  scroll-padding-block: 4px;
}
.ts-root .ts-board-rail .ts-rail-tools:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { padding: 4px; gap: 1px; }
.ts-root .ts-board-rail .ts-button:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  flex-basis: var(--ts-board-control);
  width: var(--ts-board-control) !important;
  min-width: var(--ts-board-control);
  height: var(--ts-board-control) !important;
  min-height: var(--ts-board-control);
  border-radius: 7px !important;
  color: var(--text-muted);
}
.ts-root .ts-board-rail .ts-button svg:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { width: 17px; height: 17px; stroke-width: 1.75; }
.ts-root .ts-board-rail .ts-button:hover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background: var(--ts-board-hover) !important; color: var(--text-normal); }
.ts-root .ts-board-rail .ts-button:is(.is-active, [aria-expanded=true]):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  background: var(--ts-board-active) !important;
  color: var(--ts-accent) !important;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ts-accent) 23%, transparent) !important;
}
.ts-root .ts-board-rail .ts-primary:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  background: var(--ts-board-active) !important;
  color: var(--ts-accent) !important;
  box-shadow: none !important;
}
.ts-root .ts-board-rail .ts-primary:hover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background: color-mix(in srgb, var(--ts-accent) 17%, var(--background-primary)) !important; }
.ts-root .ts-board-rail .ts-rail-divider:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { flex: 0 0 1px; height: 1px; min-height: 1px; margin: 4px 8px; background: var(--ts-board-line); }

/* Overflow uses short, consistently aligned rows. Position remains owned by
   the rail; the context menu retains its mouse-relative inline coordinates. */
.ts-root .ts-main > .ts-rail-popover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  top: 50%;
  left: 64px;
  width: 240px;
  max-width: calc(100% - 78px);
  max-height: max(40px, calc(100% - 132px));
  padding: 6px;
  border-color: var(--ts-board-line);
  border-radius: 11px;
  background: var(--ts-board-panel);
  box-shadow: var(--ts-board-menu-shadow);
  scrollbar-width: thin;
  scrollbar-color: var(--background-modifier-border) transparent;
}
.ts-root .ts-rail-popover .ts-tool-cluster:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *))::before {
  position: sticky;
  top: -6px;
  z-index: 1;
  padding: 8px 9px 5px;
  background: var(--ts-board-panel);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .01em;
}
.ts-root .ts-rail-popover .ts-tool-cluster + .ts-tool-cluster:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { margin-top: 6px; padding-top: 2px; border-top: 0; }
.ts-root .ts-rail-popover .ts-rail-actions .ts-button:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  height: 32px;
  min-height: 32px;
  border-radius: 7px;
  gap: 8px;
  padding-inline: 9px !important;
}
.ts-root .ts-rail-popover .ts-rail-actions .ts-button:hover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background: var(--ts-board-active); color: var(--text-normal); }
.ts-root .ts-rail-popover .ts-button:is(:hover, :focus-visible) > span:first-child:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { color: var(--ts-accent); }
.ts-root .ts-rail-popover .ts-button > span:first-child:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { display: flex; flex: 0 0 16px; color: var(--text-muted); }
.ts-root .ts-rail-popover .ts-button svg:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { width: 16px; height: 16px; }

/* One floating row, scrollable on a split pane. Never wrap formatting controls
   into a tall panel that covers the document being edited. */
.ts-root .ts-main > .ts-floating-formatbar:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  top: var(--ts-board-gutter);
  max-width: calc(100% - 32px);
  display: flex;
  align-items: center;
  flex-wrap: nowrap;
  min-width: 0;
  gap: 0;
  border: 1px solid var(--ts-board-line);
  border-radius: 10px;
  background: var(--ts-board-panel);
  box-shadow: var(--ts-board-shadow);
}
.ts-root .ts-main > .ts-floating-formatbar > .ts-commandbar:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  padding: 4px !important;
  gap: 0 !important;
  border: 0 !important;
  border-radius: 9px !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scroll-padding-inline: 4px;
  scrollbar-width: thin;
  scrollbar-color: var(--background-modifier-border) transparent;
}
/* The arrows own real space beside the scroll viewport, including its scrollbar. */
.ts-root .ts-floating-formatbar > .ts-format-scroll:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  flex: 0 0 26px;
  width: 26px;
  min-width: 26px;
  height: var(--ts-board-format-control);
  margin-inline: 2px;
  padding: 0 !important;
  pointer-events: auto;
}
.ts-root .ts-floating-formatbar > .ts-format-scroll svg:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { width: 15px; height: 15px; }
.ts-root .ts-floating-formatbar > .ts-format-scroll[hidden]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { display: none !important; }
.ts-root .ts-floating-formatbar .ts-commandbar > .ts-selection-tools:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  gap: var(--ts-board-format-gap) !important;
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  min-height: var(--ts-board-format-control);
  width: max-content;
  flex-wrap: nowrap;
}
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  --ts-format-value-width: 96px;
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  min-height: var(--ts-board-format-control);
  padding: 0 2px 0 7px;
  border-radius: 7px;
  background: transparent;
  color: var(--text-muted);
  white-space: nowrap;
}
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field:is(:hover, :focus-within):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background: var(--ts-board-active); }
/* Retain a visible field identity when the value is only "默认" or "混合". */
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field > span:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  display: inline-flex;
  flex: none;
  align-items: center;
  font-size: 11px;
  line-height: 1;
  font-weight: 400;
  color: var(--text-muted);
}
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field > .ts-format-label-icon:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  width: 14px;
  height: 14px;
  opacity: .8;
}
.ts-root .ts-floating-formatbar .ts-format-label-icon svg:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { width: 14px; height: 14px; stroke-width: 1.6; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field:focus-within > .ts-format-label-icon:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { color: var(--ts-accent); opacity: 1; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field select:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  height: calc(var(--ts-board-format-control) - 4px);
  min-height: calc(var(--ts-board-format-control) - 4px);
  width: var(--ts-format-value-width);
  min-width: 0;
  max-width: var(--ts-format-value-width);
  padding-inline: 6px 22px !important;
  border: 1px solid transparent;
  border-radius: 5px !important;
  background-color: transparent !important;
  color: var(--text-normal);
  box-shadow: none;
  font-size: 12px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
/* Leave room for the unit and native select arrow, including three-digit sizes. */
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field[data-format="字号"]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { --ts-format-value-width: 76px; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field:is([data-format="字体"], [data-format="卡片颜色"]):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { --ts-format-value-width: 108px; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field[data-format="范围"]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { --ts-format-value-width: 128px; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field select:hover:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) { background-color: var(--ts-board-hover) !important; }
.ts-root .ts-floating-formatbar .ts-commandbar .ts-format-field:is([data-format="字体"], [data-format="边框线型"]):not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  padding-inline-start: 8px;
  margin-inline-start: 6px;
  border-inline-start: 1px solid var(--ts-board-line);
  border-radius: 0 7px 7px 0;
}
.ts-root .ts-floating-formatbar .ts-style-transfer:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  display: flex;
  flex: none;
  align-items: center;
  gap: 1px;
  padding-inline-end: 6px;
  margin-inline-end: 4px;
  border-inline-end: 1px solid var(--ts-board-line);
}
.ts-root .ts-floating-formatbar .ts-commandbar .ts-style-transfer .ts-button:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  width: var(--ts-board-format-control);
  min-width: var(--ts-board-format-control);
  height: var(--ts-board-format-control);
  min-height: var(--ts-board-format-control);
  padding: 0 !important;
}
.ts-root .ts-floating-formatbar .ts-fill-custom input[type=color]:not(:where(.ts-calendar-plugin, .ts-calendar-plugin *)) {
  width: 24px;
  height: 24px;
  border-color: var(--ts-board-line);
  border-radius: 6px;
